[CmdletBinding()]
param([switch]$RunNodeTests)
$ErrorActionPreference='Stop';$out=[Collections.Generic.List[object]]::new();function Check($n,$ok,$d){$out.Add([pscustomobject]@{check=$n;passed=[bool]$ok;detail=$d})}
$win=[Environment]::OSVersion.Platform -eq [PlatformID]::Win32NT;Check 'Windows' $win ([Environment]::OSVersion.Version.ToString());Check 'PowerShell-7+' ($PSVersionTable.PSVersion.Major -ge 7) ($PSVersionTable.PSVersion.ToString())
$node=Get-Command node.exe -ErrorAction SilentlyContinue;if($node){$v=& $node.Source --version;Check 'Node-22-or-24' ($v -match '^v(22|24)\.') $v}else{Check 'Node-present' $false 'node.exe not found'}
$pg=Get-Command pg_dump.exe -ErrorAction SilentlyContinue;if($pg){$pv=& $pg.Source --version;Check 'PostgreSQL-client-18' ($pv -match ' 18\.') $pv}else{Check 'pg_dump-present' $false 'pg_dump.exe not found'}
$drive=Get-PSDrive -Name $env:SystemDrive.TrimEnd(':') -ErrorAction SilentlyContinue;Check 'Disk-space-5GB' ($drive -and $drive.Free -ge 5GB) $(if($drive){[math]::Round($drive.Free/1GB,2).ToString()+' GB free'}else{'system drive unavailable'})
$zone=[TimeZoneInfo]::FindSystemTimeZoneById('US Mountain Standard Time');Check 'Arizona-time-zone' ($zone.Id -eq 'US Mountain Standard Time') $zone.Id
$tmp=Join-Path $env:TEMP ('lc-validation-'+[guid]::NewGuid().ToString('N'));$sensitive=Join-Path $tmp 'dpapi.txt';$xml=Join-Path $tmp 'task.xml';$fixture=Join-Path $tmp 'fictional.bin';$archive=Join-Path $tmp 'fictional.aesgcm';$restored=Join-Path $tmp 'restored.bin';$key=Join-Path $tmp 'key.bin'
try{New-Item -ItemType Directory $tmp|Out-Null;$acl=Get-Acl $tmp;Check 'NTFS-ACL-readable' ($null -ne $acl) 'ACL inspected, no permission changes';$sample='fictional-only';$sec=ConvertTo-SecureString $sample -AsPlainText -Force;$dp=$sec|ConvertFrom-SecureString;Set-Content $sensitive $dp;$back=ConvertTo-SecureString (Get-Content -Raw $sensitive)|ConvertFrom-SecureString;Check 'DPAPI-roundtrip' ($back -eq $dp) 'Current user scope only'
if($node){[IO.File]::WriteAllBytes($fixture,[Text.Encoding]::UTF8.GetBytes('Fictional test bytes'));$k=[Security.Cryptography.RandomNumberGenerator]::GetBytes(32);[IO.File]::WriteAllBytes($key,$k);& $node.Source (Join-Path $PSScriptRoot 'crypto-cli.mjs') encrypt $fixture $archive $key *> $null;$e=$LASTEXITCODE;& $node.Source (Join-Path $PSScriptRoot 'crypto-cli.mjs') decrypt $archive $restored $key *> $null;$d=$LASTEXITCODE;Check 'AES-GCM-fictional-roundtrip' ($e -eq 0 -and $d -eq 0 -and [Linq.Enumerable]::SequenceEqual([byte[]](Get-Content -AsByteStream $fixture),[byte[]](Get-Content -AsByteStream $restored))) 'Local synthetic file; no network'
 if($RunNodeTests){Push-Location $PSScriptRoot;try{& $node.Source --test './*.test.mjs';Check 'Node-offline-tests' ($LASTEXITCODE -eq 0) 'node:test'}finally{Pop-Location}}}
 & (Join-Path $PSScriptRoot 'task-scheduler-setup.ps1') -OutputPath $xml *> $null;$task=[xml](Get-Content -Raw $xml);Check 'Scheduler-XML-valid' ($task.Task.Settings.MultipleInstancesPolicy -eq 'IgnoreNew' -and $task.Task.Settings.StartWhenAvailable -eq 'true') 'Preview generated only; no registration'
}catch{Check 'Windows-validation-exception' $false 'A local validation step failed; inspect non-secret error'}finally{Remove-Item $tmp -Recurse -Force -ErrorAction SilentlyContinue;Check 'Temp-cleanup' (-not(Test-Path $tmp)) 'Synthetic temporary files removed'}
$out|ConvertTo-Json -Depth 4;if(@($out|Where-Object{-not $_.passed}).Count){exit 1}
